function spawnCash(x,z,amount){const coin=new THREE.Mesh(new THREE.CylinderGeometry(.38,.38,.12,12),mat(0xd7b74a,.3,.5));coin.rotation.x=Math.PI/2;coin.position.set(x,.35,z);scene.add(coin);cashDrops.push({mesh:coin,amount,life:45,phase:Math.random()*6})}
function nearestCar(){let best=null,bestD=4.2;for(const c of cars){const d=dist(player.g.position,c.g.position);if(d<bestD){best=c;bestD=d}}return best}
function interact(){if(player.vehicle){const c=player.vehicle;player.vehicle=null;c.occupied=false;player.g.visible=true;player.g.position.set(c.g.position.x+2,0,c.g.position.z);player.yaw=c.g.rotation.y;toast('ON FOOT');return}
 if(shopNear){const s=shopNear;if(s.kind==='weapon'){if(player.cash>=80){player.cash-=80;player.ammo+=12;player.weapon=0;toast('AMMO RESTOCKED · +12')}else toast('NOT ENOUGH CASH · $80')}else if(s.kind==='car'){if(player.cash>=180){player.cash-=180;let p=player.g.position;let c=makeCar(p.x+3,p.z+2,0x53c6ab,player.yaw);player.vehicle=c;c.occupied=true;player.g.visible=false;toast('QUICK RIDE · TAKE THE WHEEL')}else toast('NOT ENOUGH CASH · $180')}else{if(player.cash>=120){player.cash-=120;playerBody.material=mat([0x4a668f,0x904967,0xd18d37,0x2d766b][Math.floor(Math.random()*4)]);toast('FRESH FIT · LOOK SHARP')}else toast('NOT ENOUGH CASH · $120')}updateHud();return}
 let c=nearestCar();if(c){if(c.driver){c.driver.vehicle=null;c.driver.g.visible=true;c.driver.g.position.set(c.g.position.x+2,0,c.g.position.z);c.driver=null;player.heat=Math.min(5,player.heat+1);toast('VEHICLE TAKEN · CREW ALERTED')}else toast('VEHICLE STOLEN · NICE AND EASY');player.vehicle=c;c.occupied=true;player.g.visible=false;document.getElementById('vehiclehud').classList.add('show');document.getElementById('ridepill').style.display='block';return}
 // Collect nearby dropped cash
 const d=cashDrops.findIndex(o=>dist(player.g.position,o.mesh.position)<2.4);if(d>=0){player.cash+=cashDrops[d].amount;scene.remove(cashDrops[d].mesh);cashDrops.splice(d,1);toast('PICKED UP CASH');updateHud();return}toast('NOTHING TO INTERACT WITH')
}
function shoot(){if(!started||player.vehicle||player.fireCooldown>0)return;if(player.ammo<=0){toast('OUT OF AMMO · VISIT THE GUN SHOP');return}player.ammo--;player.fireCooldown=.24;player.heat=Math.min(5,player.heat+.12);const origin=player.g.position.clone().add(new THREE.Vector3(0,1.35,0));const dir=forward();let target=null,best=34;for(const p of people){if(!p.alive)continue;const v=p.g.position.clone().add(new THREE.Vector3(0,1.1,0)).sub(origin),along=v.dot(dir),side=v.clone().addScaledVector(dir,-along).length();if(along>0&&along<best&&side<.95){best=along;target=p}}
 if(target){target.health-=player.weapon===1?52:34;toast(target.health<=0?'TARGET DOWN · CASH DROPPED':'HIT CONFIRMED');if(target.health<=0){target.alive=false;target.g.rotation.z=Math.PI/2;target.g.position.y=.35;target.weapon=false;spawnCash(target.g.position.x,target.g.position.z,15+Math.floor(Math.random()*36));if(target.gang>=0)player.heat=Math.min(5,player.heat+.7)}else if(target.gang<0){target.flee=true}updateHud()}
 // Muzzle flash + tracers are brief, simple emissive geometry
 const flash=new THREE.Mesh(new THREE.SphereGeometry(.12,6,5),new THREE.MeshBasicMaterial({color:0xffdd85}));flash.position.copy(origin).addScaledVector(dir,1);scene.add(flash);setTimeout(()=>scene.remove(flash),55);
}
function upgradeWeapon(n){if(n===1){if(player.cash>=320){player.cash-=320;player.weapon=1;player.ammo=Math.max(player.ammo,30);toast('SMG EQUIPPED · FAST FIRE')}else toast('SMG COSTS $320')}else if(n===2){player.weapon=0;toast('PISTOL EQUIPPED')}else if(n===3){player.weapon=2;toast('UNARMED · HANDS UP')}updateHud()}
function rayBlocked(a,b){for(const bl of buildings){if(Math.abs(a.x-bl.x)<bl.w/2+.5&&Math.abs(a.z-bl.z)<bl.d/2+.5)return true}return false}
function collide(x,z,r=.62){for(const bl of buildings)if(Math.abs(x-bl.x)<bl.w/2+r&&Math.abs(z-bl.z)<bl.d/2+r)return true;return false}
function updatePeople(dt){for(const p of people){if(!p.alive)continue;p.think-=dt;p.phase+=dt*4;let pos=p.g.position;if(p.driver&&p.vehicle){continue}
 if(p.gang>=0){let enemy=null,bd=28;for(const q of people)if(q.alive&&q.gang>=0&&q.gang!==p.gang){let d=dist(pos,q.g.position);if(d<bd){bd=d;enemy=q}}if(enemy){const toward=enemy.g.position.clone().sub(pos);let angle=Math.atan2(-toward.x,-toward.z);p.g.rotation.y=angle;if(bd>8){pos.x+=Math.sin(angle)*dt*1.1;pos.z+=Math.cos(angle)*dt*1.1}else if(p.think<=0){p.think=2.2+Math.random()*1.8;if(Math.random()<.58){enemy.health-=15;enemy.g.rotation.y=angle+Math.PI;if(enemy.health<=0){enemy.alive=false;enemy.g.position.y=.35;enemy.g.rotation.z=Math.PI/2;spawnCash(enemy.g.position.x,enemy.g.position.z,20+Math.floor(Math.random()*30))}}}}}
 else if(p.flee){let away=pos.clone().sub(player.g.position);let angle=Math.atan2(away.x,away.z);pos.x+=Math.sin(angle)*dt*3;pos.z+=Math.cos(angle)*dt*3;p.g.rotation.y=angle;if(Math.random()<.008)p.flee=false}
 else if(p.think<=0){p.think=2+Math.random()*4;p.target=new THREE.Vector3(pos.x+(Math.random()-.5)*8,0,pos.z+(Math.random()-.5)*8)}else if(p.target){let delta=p.target.clone().sub(pos);if(delta.length()>.3){delta.normalize();p.g.rotation.y=Math.atan2(-delta.x,-delta.z);let nx=pos.x+delta.x*dt*p.speed,nz=pos.z+delta.z*dt*p.speed;if(!collide(nx,nz,.4)){pos.x=nx;pos.z=nz}}}
 p.g.position.y=Math.abs(Math.sin(p.phase))*.045;
 }
 // Dropped loot bobs and is magnetically collected on foot
 for(let i=cashDrops.length-1;i>=0;i--){const o=cashDrops[i];o.life-=dt;o.mesh.position.y=.35+Math.sin(gameTime*3+o.phase)*.12;o.mesh.rotation.y+=dt*1.1;if(dist(player.g.position,o.mesh.position)<1.55&&!player.vehicle){player.cash+=o.amount;scene.remove(o.mesh);cashDrops.splice(i,1);toast('+$'+o.amount+' CASH');updateHud()}else if(o.life<=0){scene.remove(o.mesh);cashDrops.splice(i,1)}}
}
function updateCars(dt){for(const c of cars){if(player.vehicle===c)continue;if(c.driver){c.speed=2.1;const g=c.g;g.position.x+=Math.sin(g.rotation.y)*c.speed*dt;g.position.z+=Math.cos(g.rotation.y)*c.speed*dt;if(Math.abs(g.position.x)>145||Math.abs(g.position.z)>145){g.rotation.y+=Math.PI/2;c.speed=0}for(const p of people){if(p.alive&&!p.driver&&dist(p.g.position,g.position)<2.1&&Math.random()<dt*.4)p.flee=true}}else{c.speed*=.96}}
 if(player.vehicle){let c=player.vehicle,forwardSpeed=(keys.KeyW?1:0)-(keys.KeyS?1:0);c.speed+=(forwardSpeed*14*dt);c.speed*=keys.Space?.91:.985;c.speed=THREE.MathUtils.clamp(c.speed,-8,22);let steer=(keys.KeyA?1:0)-(keys.KeyD?1:0);c.g.rotation.y+=steer*dt*Math.sign(c.speed||1)*Math.min(1,Math.abs(c.speed)/5)*1.6;c.g.position.x+=-Math.sin(c.g.rotation.y)*c.speed*dt;c.g.position.z+=-Math.cos(c.g.rotation.y)*c.speed*dt;if(collide(c.g.position.x,c.g.position.z,1.1)){c.g.position.x-= -Math.sin(c.g.rotation.y)*c.speed*dt;c.g.position.z-= -Math.cos(c.g.rotation.y)*c.speed*dt;c.speed*=-.25}for(const p of people)if(p.alive&&dist(p.g.position,c.g.position)<1.6&&Math.abs(c.speed)>4){p.alive=false;p.g.position.y=.35;p.g.rotation.z=Math.PI/2;spawnCash(p.g.position.x,p.g.position.z,12)}document.getElementById('speed').textContent=Math.round(Math.abs(c.speed)*4);player.g.position.copy(c.g.position)}else document.getElementById('vehiclehud').classList.remove('show')}

